-- 43 · lectura de estado (solo SELECT). Antes y después de P2, de cada
-- aplicación y ante cualquier respuesta ambigua. Usa las mismas huellas que
-- el ensayo P2 (comportamiento y completa).
select 'huella_comportamiento' k, pg_catalog.md5((select md5(prosrc) || proacl::text from pg_proc where oid = 'public.catalog_published_prices(text[], text, integer)'::regprocedure) || (select md5(prosrc) || proacl::text from pg_proc where oid = 'public.enforce_active_project_limit()'::regprocedure) || coalesce((select string_agg(tablename || policyname || permissive || cmd || roles::text || coalesce(qual, '') || coalesce(with_check, ''), '|' order by tablename, policyname)     from pg_policies where schemaname = 'public' and tablename in ('projects', 'project_products', 'rfqs')), '') || (select string_agg(id || ':' || max_active_projects || ':' || max_users, '|' order by id) from public.plans) || (select string_agg(tgname || pg_get_triggerdef(oid), '|' order by tgname) from pg_trigger where tgrelid = 'public.projects'::regclass and not tgisinternal)) v
union all select 'huella_completa', pg_catalog.md5(pg_catalog.md5((select md5(prosrc) || proacl::text from pg_proc where oid = 'public.catalog_published_prices(text[], text, integer)'::regprocedure) || (select md5(prosrc) || proacl::text from pg_proc where oid = 'public.enforce_active_project_limit()'::regprocedure) || coalesce((select string_agg(tablename || policyname || permissive || cmd || roles::text || coalesce(qual, '') || coalesce(with_check, ''), '|' order by tablename, policyname)     from pg_policies where schemaname = 'public' and tablename in ('projects', 'project_products', 'rfqs')), '') || (select string_agg(id || ':' || max_active_projects || ':' || max_users, '|' order by id) from public.plans) || (select string_agg(tgname || pg_get_triggerdef(oid), '|' order by tgname) from pg_trigger where tgrelid = 'public.projects'::regclass and not tgisinternal)) || (select json_agg(p order by p.id)::text from public.plans p) || (select string_agg(table_name || '.' || column_name || ':' || data_type || ':' || coalesce(column_default, ''), '|' order by table_name, ordinal_position)     from information_schema.columns where table_schema = 'public' and table_name in ('plans', 'profiles')) || coalesce((select string_agg(n.nspname || '.' || p.proname || md5(p.prosrc) || coalesce(p.proacl::text, ''), '|' order by n.nspname, p.proname)     from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public', 'mobau_private')), '') || (select count(*)::text from pg_policies where schemaname in ('public', 'mobau_private')) || coalesce(to_regclass('mobau_private.plan_events')::text, 'sin-plan_events') || md5(coalesce((select string_agg(id::text || status || coalesce(studio_id::text, '-') || owner_user_id::text || name || updated_at::text, '|' order by id) from public.projects), '')     || coalesce((select string_agg(id::text || quantity::text || coalesce(unit, '-') || selected_for_rfq::text, '|' order by id) from public.project_products), '')     || coalesce((select string_agg(id::text || status, '|' order by id) from public.rfqs), '')     || coalesce((select string_agg(id::text || plan || role || subscription_status, '|' order by id) from public.profiles), '')     || coalesce((select string_agg(id::text, '|' order by id) from public.studios), '')))
union all select 'migraciones', (select count(*)::text || ' / ' || max(version) from supabase_migrations.schema_migrations)
union all select 'planes', (select string_agg(id || ':' || name || ':' || max_active_projects || ':' || max_users || ':' || coalesce(trial_days::text, 'null'), ' | ' order by id) from public.plans)
union all select 'objetos T1', coalesce(to_regprocedure('public.my_professional_access()')::text, 'sin función') || ' / ' || coalesce(to_regclass('mobau_private.plan_events')::text, 'sin plan_events')
union all select 'políticas projects/lines/rfqs', (select count(*)::text from pg_policies where schemaname = 'public' and tablename in ('projects', 'project_products', 'rfqs'))
union all select 'catalog_published_prices md5', (select md5(prosrc) from pg_proc where oid = 'public.catalog_published_prices(text[], text, integer)'::regprocedure)
union all select 'enforce_active_project_limit md5', (select md5(prosrc) from pg_proc where oid = 'public.enforce_active_project_limit()'::regprocedure)
union all select 'cuentas de prueba', (select string_agg(left(id::text, 8) || ':' || role || ':' || plan, ' | ' order by id::text) from public.profiles
                                        where left(id::text, 8) in ('e2a655c1', '743270cd', '5b4f13c8', '392a9eb4', 'a8fe42e8'))
union all select 'proyectos/líneas/solicitudes', (select count(*)::text from public.projects) || ' / ' || (select count(*)::text from public.project_products) || ' / ' || (select count(*)::text from public.rfqs)
union all select 'estudios', (select count(*)::text from public.studios);
